text=text.replace('<p class="hero-lead">Você escolhe o que vender.<br>A Madame mostra onde procurar.</p>','')
text=text.replace('20 listas digitais para explorar fornecedores,<br class="desktop-break"> consultar informações e começar sua pesquisa.','Explore 20 listas digitais organizadas por segmento e encontre caminhos para pesquisar fornecedores para o seu negócio.')
text=text.replace('Quero explorar as listas','Conhecer as listas')
text=text.replace('<div class="hero-seal"','<img class="hero-portrait" src="assets/madame.webp" width="850" height="1140" alt="Madame de blazer rosa, personagem da marca" fetchpriority="high">\n        <div class="hero-seal"')
text=text.replace('O olhar de quem ama garimpar.','Um convite para descobrir.')
